def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            comps.append((color, cells))
    # The long L-shaped component is the color key. Recolor the lone small
    # non-key object of the otherwise unpaired color to that key color.
    guides = []
    for color, cells in comps:
        rs = {r for r, c in cells}
        cs = {c for r, c in cells}
        if len(cells) >= 8 and len(rs) >= 4 and len(cs) >= 4:
            guides.append((len(cells), color))
    if not guides:
        return [row[:] for row in grid]
    guide = max(guides)[1]
    candidates = [(len(cells), color, cells) for color, cells in comps
                  if color != guide and len(cells) <= 3]
    if not candidates:
        return [row[:] for row in grid]
    _, _, target = min(candidates, key=lambda x: (x[0], min(r for r,c in x[2]), min(c for r,c in x[2])))
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = guide
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
